   466  // Consumes b_info header block and sz_cpr data block from input file 'fi'.
   467  // De-compresses; appends to output file 'fo' unless rewrite or peeking.
   468  // For "peeking" without writing: set (fo = nullptr), (is_rewrite = -1)
   469  // Return actual length when peeking; else 0.
   470  unsigned PackUnix::unpackExtent(unsigned wanted, OutputFile *fo,
   471      unsigned &c_adler, unsigned &u_adler,
   472      bool first_PF_X,
   473      int is_rewrite // 0(false): write; 1(true): rewrite; -1: no write
   474  )
   475  {
   476      b_info hdr; memset(&hdr, 0, sizeof(hdr));
   477      unsigned inlen = 0; // output index (if-and-only-if peeking)
   478      while (wanted) {
   479          fi->readx(&hdr, szb_info);
   480          int const sz_unc = ph.u_len = get_te32(&hdr.sz_unc);
   481          int const sz_cpr = ph.c_len = get_te32(&hdr.sz_cpr);
   482          ph.filter_cto = hdr.b_cto8;
   483
   484          if (sz_unc == 0) { // must never happen while 0!=wanted
   485              throwCantUnpack("corrupt b_info");
   486              break;
   487          }
   488          if (sz_unc <= 0 || sz_cpr <= 0)
   489              throwCantUnpack("corrupt b_info");
   490          if (sz_cpr > sz_unc || sz_unc > (int)blocksize)
   491              throwCantUnpack("corrupt b_info");
   492
   493          // place the input for overlapping de-compression
   494          // FIXME: inlen cheats OVERHEAD; assumes small wanted peek length
   495          int j = inlen + blocksize + OVERHEAD - sz_cpr;
   496          fi->readx(ibuf+j, sz_cpr);
   497          total_in += sz_cpr;
   498          // update checksum of compressed data
   499          c_adler = upx_adler32(ibuf + j, sz_cpr, c_adler);
   500
   501          if (sz_cpr < sz_unc) { // block was compressed
   502              decompress(ibuf+j, ibuf+inlen, false);
   503              if (12==szb_info) { // modern per-block filter
   504                  if (hdr.b_ftid) {
   505                      Filter ft(ph.level);  // FIXME: ph.level for b_info?
   506                      ft.init(hdr.b_ftid, 0);
   507                      ft.cto = hdr.b_cto8;
   508                      ft.unfilter(ibuf+inlen, sz_unc);
   509                  }
   510              }
   511              else { // ancient per-file filter
   512                  if (first_PF_X) { // Elf32_Ehdr is never filtered
   513                      first_PF_X = false;  // but everything else might be
   514                  }
   515                  else if (ph.filter) {
   516                      Filter ft(ph.level);
   517                      ft.init(ph.filter, 0);
   518                      ft.cto = (unsigned char) ph.filter_cto;
   519                      ft.unfilter(ibuf+inlen, sz_unc);
   520                  }
   521              }
   522          }
   523          else if (sz_cpr == sz_unc) { // slide literal (non-compressible) block
   524              memmove(&ibuf[inlen], &ibuf[j], sz_unc);
   525          }
   526          // update checksum of uncompressed data
   527          u_adler = upx_adler32(ibuf + inlen, sz_unc, u_adler);
   528          // write block
   529          if (fo) {
   530              if (is_rewrite) {
   531                  fo->rewrite(ibuf, sz_unc);
   532              }
   533              else {
   534                  fo->write(ibuf, sz_unc);
   535                  total_out += sz_unc;
   536              }
   537          }
   538          else if (is_rewrite < 0) { // append to &ibuf[inlen]
   539              inlen += sz_unc;  // accounting; data is already there
   540              if (wanted <= (unsigned)sz_unc)  // done
   541                  break;
   542          }
   543          else if (wanted < (unsigned)sz_unc) // mismatched end-of-block
   544              throwCantUnpack("corrupt b_info");
   545          else { // "upx -t": (!fo && !(is_rewrite < 0))
   546              // No output.
   547          }
   548          wanted -= sz_unc;
   549      }
   550      return inlen;
   551  }
